#!/usr/bin/env python3
"""Build Ming's offline illustrated review from measured simulation artifacts."""
import argparse,base64,html,json
from pathlib import Path

def render(root):
    b=json.loads((root/'browser-check.json').read_text());n=json.loads((root/'native-check.json').read_text());m=json.loads((root/'current-geometry/published-mapping.json').read_text())
    def pic(name,caption):
        data=base64.b64encode((root/name).read_bytes()).decode()
        return '<figure><img src="data:image/png;base64,'+data+'" alt="'+html.escape(caption)+'"><figcaption>'+html.escape(caption)+'</figcaption></figure>'
    live=b['after_201_steps'];fmt=lambda x:f'{x:,.2f}'
    checks=''.join('<li>'+html.escape(c)+'</li>' for c in b['checks'])
    doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Microduck — mechanical simulation review</title><style>
    body{font:17px/1.6 Segoe UI,Arial,sans-serif;color:#243247;background:#f4f6f9;margin:0}main{max-width:1200px;margin:auto;padding:32px}h1{font-size:38px;line-height:1.2}h2{font-size:25px}p{max-width:950px}section{background:white;border:1px solid #d9e0ea;border-radius:14px;padding:24px;margin:22px 0}figure{margin:22px 0}img{display:block;width:100%;height:auto;border-radius:10px}figcaption{font-size:14px;color:#586579;margin:8px 0}.status{padding:15px 20px;background:#fff2dc;border-left:5px solid #b97700}.fail{background:#ffe9e7;border-left:5px solid #b92b26;padding:16px}.grid{display:flex;flex-wrap:wrap;gap:15px}.metric{flex:1;min-width:170px;background:#f4f6f9;border-radius:10px;padding:16px}.metric b{font-size:28px;display:block}code{overflow-wrap:anywhere;font-size:12px}a{color:#2453a7}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #d9e0ea;text-align:left;padding:10px}@media print{body{background:white}main{padding:0}section{break-inside:avoid}a{color:inherit}}
    </style><main><h1>Microduck<br>Mechanical simulation review / 机械仿真检查</h1>
    <p>The whole robot is now connected to a real rigid-body physics engine in ce-cad. Its 14 motor joints move under gravity, motor forces and contact with the floor.</p>
    <p>整个机器人已接入物理仿真：14 个电机关节、重力、电机力矩和地面接触。此文件可直接离线打开，所有图片均已包含。</p>
    <div class="status"><b>Engineering review — manufacturing approval remains pending.<br>工程评审资料 — 尚未批准制造。</b><br>Motor characteristics, part strength and cable flex still require validation on our build.</div>'''
    doc+='<section><h2>1. The complete robot / 完整机器人</h2>'+pic('live-bench.png','The actual published assembly in ce-cad. Every shown piece comes from the published geometry; it is not an AI illustration.')
    doc+='<div class="grid"><div class="metric"><b>'+str(m['parts'])+'</b>placed pieces / 零件实例</div><div class="metric"><b>14</b>motor joints / 电机关节</div><div class="metric"><b>'+str(len(b['checks']))+'</b>browser checks passed / 浏览器检查通过</div></div></section>'
    doc+='<section><h2>2. Real physics step / 真实物理计算</h2><p>The joint sliders command motor angles. The solver calculates where the robot actually moves; the picture follows that calculated state.</p>'+pic('live-0402s.png','Measured live state after '+str(live['steps'])+' physics steps: '+fmt(live['time_s'])+' seconds, '+str(live['contacts'])+' contacts, '+fmt(live['max_torque_Nmm'])+' N mm maximum actuator torque at this instant.')
    doc+='<p>During the independent four-second native-engine run, the study recorded '+str(n['peak_contacts'])+' peak contact points and '+fmt(n['peak_torque_Nmm'])+' N mm peak actuator torque. The largest joint-limit excess was '+fmt(n['max_limit_excess_deg'])+' degrees.</p></section>'
    doc+='<section><h2>3. What needs fixing or proving / 仍需解决和验证</h2><div class="fail"><b>Standing test: '+html.escape(n['standing_stability'])+' / 站立测试未通过</b><br>The open-loop motor-angle hold fell during the four-second test. The lowest body reference height was '+fmt(n['min_root_z_mm'])+' mm. Balance-controller behavior has not been established by this test.<br>固定电机目标角度、未运行平衡控制时，机器人在测试中倒下。此结果不能证明平衡软件运行时的表现。</div><table><tr><th>Question / 问题</th><th>Current result / 当前结果</th></tr><tr><td>Can the complete robot be articulated?</td><td>Yes: 14 named motor joints, sourced axes and limits.</td></tr><tr><td>Will the printed legs and mounts hold the loads?</td><td>CANNOT DETERMINE — deformation and strength were not solved.</td></tr><tr><td>Does every screw or bearing fit?</td><td>CANNOT DETERMINE — collision meshes use convex hulls and do not prove hole or fastener fit.</td></tr><tr><td>Are cables safe throughout movement?</td><td>CANNOT DETERMINE — flexible cable dynamics are outside this study.</td></tr><tr><td>Which servos are modeled?</td><td>ROBOTIS XL330-M288-T in the published assembly. No cheaper-servo substitution has been made in this study.</td></tr></table></section>'
    doc+='<section><h2>4. How this was checked / 检查方法</h2><ul>'+checks+'</ul><p>All '+str(m['triangles'])+' published triangles were transformed into the moving body frames. Maximum round-trip coordinate error, including the written STL precision: '+format(m['world_roundtrip_max_mm'],'.3g')+' mm. The 14 joint origins and axes were cross-checked against the existing measured joint records.</p><p>MuJoCo '+html.escape(n['engine'])+' computed '+str(n['steps'])+' native physics steps in '+fmt(n['cpu_seconds'])+' CPU seconds. The browser and native engine can produce small numerical/contact differences; these are separately recorded.</p><p>Collision meshes are convex hulls. Adjacent parent-child contacts are filtered. Upstream inertia, friction and actuator fits remain assumptions for this build.</p><details><summary>Exact source geometry / 几何文件版本</summary><code>SHA-256 '+html.escape(m['source_sha256'])+'</code><p>This report identifies the measured published snapshot. Later geometry changes require the study and screenshots to be regenerated.</p></details></section><section><h2>Optional interactive view / 可选交互查看</h2><p>On Leif’s workstation, <a href="http://127.0.0.1:8765/web/microduck.html?pose=STAND">open the ce-cad simulation bench</a>, then choose “Start live physics”. This workstation-only link is optional; Ming can review all images and results above offline on Windows.</p></section></main></html>'
    (root/'Mechanical simulation review.html').write_text(doc)
    print(root/'Mechanical simulation review.html')
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('root',type=Path);render(ap.parse_args().root)
